'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "width": 231.0,
  "height": 78.0,
  "autosize": {
    "type": "pad"
  },
  "layer": [
    {
      "mark": {
        "type": "bar",
        "cornerRadius": 6
      },
      "encoding": {
        "y": {
          "field": "Delivery Status",
          "type": "nominal",
          "sort": [
            "Delivered",
            "Failed",
            "Pending"
          ],
          "scale": {
            "domain": [
              "Delivered",
              "Failed",
              "Pending"
            ],
            "paddingInner": 0.45
          },
          "title": null,
          "axis": {
            "labelColor": "#344054",
            "labelFontSize": 10.5
          }
        },
        "x": {
          "type": "quantitative",
          "title": null,
          "scale": {
            "domain": [
              0,
              0.4
            ]
          },
          "axis": null,
          "field": "Pilot No-show Rate"
        },
        "color": {
          "field": "Delivery Status",
          "type": "nominal",
          "scale": {
            "domain": [
              "Delivered",
              "Failed",
              "Pending"
            ],
            "range": [
              "#1BAF7A",
              "#E34948",
              "#A7B1C2"
            ]
          },
          "legend": null
        },
        "tooltip": [
          {
            "field": "Delivery Status"
          },
          {
            "field": "Pilot No-show Rate",
            "format": ".1%"
          },
          {
            "field": "Pilot Eligible Appointments",
            "format": ","
          }
        ]
      }
    },
    {
      "transform": [
        {
          "calculate": "format(datum[''Pilot No-show Rate''], ''.1%'') + ''  n='' + format(datum[''Pilot Eligible Appointments''], '','')",
          "as": "t"
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "dx": 6,
        "fontSize": 10,
        "color": "#101828"
      },
      "encoding": {
        "y": {
          "field": "Delivery Status",
          "type": "nominal",
          "sort": [
            "Delivered",
            "Failed",
            "Pending"
          ],
          "scale": {
            "domain": [
              "Delivered",
              "Failed",
              "Pending"
            ],
            "paddingInner": 0.45
          },
          "title": null,
          "axis": {
            "labelColor": "#344054",
            "labelFontSize": 10.5
          }
        },
        "x": {
          "type": "quantitative",
          "title": null,
          "scale": {
            "domain": [
              0,
              0.4
            ]
          },
          "axis": null,
          "field": "Pilot No-show Rate"
        },
        "text": {
          "field": "t"
        }
      }
    }
  ]
}'

'{
  "background": null,
  "font": "Segoe UI",
  "view": {
    "stroke": null
  },
  "padding": 2,
  "axis": {
    "labelFont": "Segoe UI",
    "labelFontSize": 10,
    "labelColor": "#667085",
    "titleFont": "Segoe UI",
    "titleFontSize": 10,
    "titleColor": "#667085",
    "titleFontWeight": "normal",
    "domain": false,
    "ticks": false,
    "gridColor": "#EEF0F4",
    "labelPadding": 6
  },
  "legend": {
    "labelFont": "Segoe UI",
    "labelFontSize": 10.5,
    "labelColor": "#344054",
    "symbolType": "circle",
    "symbolSize": 70,
    "title": null,
    "orient": "top",
    "direction": "horizontal",
    "columnPadding": 14
  },
  "text": {
    "font": "Segoe UI",
    "fontSize": 11,
    "color": "#344054"
  },
  "title": {
    "font": "Segoe UI"
  },
  "concat": {
    "spacing": 8
  }
}'
